#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// scripts/check-skip-critical-e2e.mjs — generated by arbiter (anti-fake-green, #1497).
//
// Skipped-critical-e2e guard. A critical-path end-to-end test that is skipped is a fake-green: the
// highest-value reality-contact signal goes green without ever running. This guard scans
// playwright/cypress/wdio e2e spec dirs for skipped specs (test.skip/it.skip/xtest/.fixme), and
// treats a skip on a spec tagged @critical-path as the worst case. If NO e2e config is present the
// verdict is NA (exit 0) — there is nothing to skip, so never a manufactured fail.
//
// Exit codes (INV-53): 0=PASS / NA (no e2e config), 1=FAIL (skipped e2e spec), 2=ERROR.
// Usage: node scripts/check-skip-critical-e2e.mjs [--dir <path>] [--help]
import { readdirSync, statSync, readFileSync, existsSync } from 'node:fs'
import { join, resolve } from 'node:path'

const args = process.argv.slice(2)
if (args.includes('--help') || args.includes('-h')) {
  process.stdout.write(
    'Usage: node scripts/check-skip-critical-e2e.mjs [--dir <path>]\n' +
      '  Fails when a critical-path e2e spec is skipped. If no e2e config exists → NA (exit 0).\n' +
      '  Add `// skip-critical-e2e-exempt: <reason>` on the skip line or the line above to audit-\n' +
      '  exempt a legitimate skip.\n',
  )
  process.exit(0)
}
const dirArgIdx = args.indexOf('--dir')
const ROOT = dirArgIdx >= 0 && args[dirArgIdx + 1] ? resolve(args[dirArgIdx + 1]) : process.cwd()

// #1840 F4 tranche-3: '.venv'/'venv'/'__pycache__' — a Python dependency's
// bundled test suite inside site-packages must never be scanned as project
// code (mirrors lib/glob-walk.mjs's SKIP_DIRS).
const SKIP_DIRS = new Set([
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.coverage',
  '.venv',
  'venv',
  '__pycache__',
])

// e2e config signals — if none exists, there is no e2e surface to skip (verdict NA).
const E2E_CONFIG_FILES = [
  'playwright.config.ts',
  'playwright.config.js',
  'playwright.config.mjs',
  'cypress.config.ts',
  'cypress.config.js',
  'cypress.config.mjs',
  'wdio.conf.ts',
  'wdio.conf.js',
]

// Directory names that conventionally hold e2e specs.
const E2E_DIR_NAMES = new Set(['e2e', 'playwright', 'cypress', 'integration-e2e'])

const SPEC_RE = /\.(?:spec|test|e2e)\.(?:ts|tsx|js|jsx|mjs)$/

// Skip markers anchored to statement start (a string mention is not a skip).
const SKIP_RE = /^(?:await\s+)?(?:test|it|describe)\.(?:skip|fixme)\s*\(|^x(?:test|it|describe)\s*\(/
const CRITICAL_RE = /@critical-path\b/
const EXEMPT_RE = /skip-critical-e2e-exempt:\s*\S/

function hasE2eConfig() {
  return E2E_CONFIG_FILES.some((f) => existsSync(join(ROOT, f)))
}

/** Collect spec files that live under an e2e-named directory. */
function collectE2eSpecs(dir, acc, inE2eTree) {
  let entries
  try {
    entries = readdirSync(dir)
  } catch {
    return
  }
  for (const entry of entries) {
    if (SKIP_DIRS.has(entry)) continue
    const full = join(dir, entry)
    let st
    try {
      st = statSync(full)
    } catch {
      continue
    }
    if (st.isDirectory()) {
      collectE2eSpecs(full, acc, inE2eTree || E2E_DIR_NAMES.has(entry))
    } else if (inE2eTree && SPEC_RE.test(entry)) {
      acc.push(full)
    }
  }
}

function main() {
  if (!hasE2eConfig()) {
    process.stdout.write('check-skip-critical-e2e: NA — no e2e config (playwright/cypress/wdio)\n')
    return 0
  }

  const specs = []
  collectE2eSpecs(ROOT, specs, false)

  const violations = []
  for (const file of specs) {
    let content
    try {
      content = readFileSync(file, 'utf-8')
    } catch {
      continue
    }
    const lines = content.split('\n')
    // A spec file is "critical-path" if any line carries the tag (annotation or title token).
    const fileCritical = lines.some((l) => CRITICAL_RE.test(l))
    for (let i = 0; i < lines.length; i++) {
      const trimmed = lines[i].trim()
      const prev = i > 0 ? lines[i - 1] : ''
      if (EXEMPT_RE.test(lines[i]) || EXEMPT_RE.test(prev)) continue
      if (SKIP_RE.test(trimmed)) {
        const crit = fileCritical || CRITICAL_RE.test(trimmed) || CRITICAL_RE.test(prev)
        violations.push(`  ${file}:${i + 1}${crit ? ' [@critical-path]' : ''}: ${trimmed}`)
      }
    }
  }

  if (violations.length > 0) {
    process.stderr.write(
      `check-skip-critical-e2e: ${violations.length} skipped e2e spec(s) — a skipped e2e is a fake-green:\n`,
    )
    for (const v of violations) process.stderr.write(v + '\n')
    return 1
  }
  process.stdout.write(`check-skip-critical-e2e: OK — ${specs.length} e2e spec(s), none skipped\n`)
  return 0
}

try {
  process.exit(main())
} catch (e) {
  process.stderr.write(`check-skip-critical-e2e: ERROR — ${e?.message ?? e}\n`)
  process.exit(2)
}
